<section class="panel account-box"><span class="eyebrow">TÀI KHOẢN E-SHOP</span><h1 class="page-title mt-3"><?= e($title) ?></h1><p class="muted">Mọi thiết bị bạn cần, trong một tài khoản.</p><form method="post" action="<?= $register?'/register':'/login' ?>"><?= App\Core\Csrf::field() ?><?php if($register):?><label class="form-label" for="auth-name">Họ và tên</label><input class="form-control" id="auth-name" name="name" required maxlength="120" autocomplete="name"><?php endif?><label class="form-label" for="auth-email">Email</label><input class="form-control" id="auth-email" type="email" name="email" required maxlength="190" autocomplete="username"><label class="form-label" for="auth-password">Mật khẩu<?= $register?' (tối thiểu 10 ký tự)':'' ?></label><input class="form-control" id="auth-password" type="password" name="password" required maxlength="72" <?= $register?'minlength="10"':'' ?> autocomplete="<?= $register?'new-password':'current-password' ?>"><?php if($register):?><label class="form-label" for="auth-confirm">Nhập lại mật khẩu</label><input class="form-control" id="auth-confirm" type="password" name="password_confirmation" required autocomplete="new-password"><?php endif?><button class="btn btn-primary w-100 mt-4" id="auth-submit" type="submit"><?= $register?'Tạo tài khoản':'Đăng nhập' ?></button></form><p class="text-center mt-4 mb-0 small"><a href="<?= $register?'/login':'/register' ?>"><?= $register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký ngay' ?></a></p></section>
